import json, urllib.request, urllib.parse, os, io
from concurrent.futures import ThreadPoolExecutor
from PIL import Image

ITEMS = {
 'A_nosferatu': ('nosferatu-phantom-der-nacht-werner-herzog-1979', 'Nosferatu- Phantom Der Nacht -Werner Herzog (1979).mp4'),
 'B_exorcist3': ('the-exorcist-iii_202501', 'The Exorcist III.mp4'),
 'C_apollo18': ('apollo-18_202403', 'Apollo 18.mp4'),
 'D_sleepaway': ('sleepaway-camp-1983_202510', 'sleepaway-camp-1983.mp4'),
 'E_dotd': ('day-of-the-dead-1985_202503', 'Day of the Dead (1985).mp4'),
 'F_littleshop': ('TheLittleShopOfHorrors1960', 'The-Little-Shop-of-Horrors.mp4'),
 'G_promnight': ('prom-night_202510', 'prom night.mp4'),
 'J_blackxmas': ('black-christmas-1974-uncut', 'Black Christmas 1974 UNCUT.mp4'),
}

def fetch(url, tries=3):
    for i in range(tries):
        try:
            req = urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
            return urllib.request.urlopen(req, timeout=40).read()
        except Exception as e:
            err = e
    raise err

def process(key, ident, videobase):
    prefix = videobase.rsplit('.',1)[0]
    meta = json.loads(fetch('https://archive.org/metadata/%s' % ident))
    thumbs = [f['name'] for f in meta.get('files',[]) if '.thumbs/' in f['name'] and f['name'].split('.thumbs/')[1].startswith(prefix)]
    thumbs.sort()
    out = {'key':key,'ident':ident,'n':len(thumbs),'colors':[]}
    def get_one(name):
        url = 'https://archive.org/download/%s/%s' % (ident, urllib.parse.quote(name))
        b = fetch(url)
        im = Image.open(io.BytesIO(b)).convert('RGB')
        im.thumbnail((64,64))
        arr = list(im.resize((1,1), Image.BOX).getdata()[0])
        return (name, arr)
    with ThreadPoolExecutor(max_workers=8) as ex:
        results = list(ex.map(get_one, thumbs))
    results.sort(key=lambda r: r[0])
    out['colors'] = [r[1] for r in results]
    out['names'] = [r[0] for r in results]
    json.dump(out, open('thumbs/%s.json'%key,'w'))
    print(key, out['n'], 'thumbs ok')
    return out

from concurrent.futures import as_completed
with ThreadPoolExecutor(max_workers=4) as ex:
    futs = {ex.submit(process, k, v[0], v[1]): k for k,v in ITEMS.items()}
    for f in as_completed(futs):
        try: f.result()
        except Exception as e: print(futs[f], 'FAIL', repr(e)[:100])
EOF

